CREATE OR REPLACE FUNCTION public.factory_native_embed_publication_v1(p_catalog integer, p_version integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE engine text;expected_slug text;
BEGIN
 SELECT t.engine,t.slug INTO engine,expected_slug FROM (VALUES(218,'launch-square-calculator','square-calculator'),(219,'launch-cube-calculator','cube-calculator'),(220,'launch-square-root-calculator','square-root-calculator'),(423,'conversion.length','length-converter'),(430,'conversion.energy','energy-converter'),(431,'conversion.power','power-converter'),(432,'conversion.time','time-converter'),(438,'conversion.force','force-converter'),(440,'conversion.frequency','frequency-converter'),(208,'launch-percentage-change-calculator','percentage-change-calculator'),(209,'launch-percentage-increase-calculator','percentage-increase-calculator'),(210,'launch-percentage-decrease-calculator','percentage-decrease-calculator'),(211,'launch-ratio-calculator','ratio-calculator'),(212,'launch-proportion-calculator','proportion-calculator'),(215,'launch-fraction-to-decimal-calculator','fraction-to-decimal-calculator'),(216,'launch-average-two-numbers-calculator','average-two-numbers-calculator'),(424,'conversion.area','area-converter'),(425,'conversion.volume','volume-converter'),(427,'conversion.temperature','temperature-converter'),(428,'conversion.speed','speed-converter'),(433,'conversion.angle','angle-converter'),(434,'conversion.data-storage','data-storage-converter'),(322,'physics.capacitance','capacitance-calculator'),(325,'physics.free-fall','free-fall-calculator'),(327,'physics.angular-velocity','angular-velocity-calculator'))t(catalog,engine,slug) WHERE t.catalog=p_catalog;
 IF NOT FOUND OR p_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Exact publication unavailable' USING ERRCODE='PT404';END IF;
 IF NOT public.factory_native_embed_publication_snapshot_v1(engine,expected_slug,p_version) THEN RAISE EXCEPTION 'Exact publication unavailable' USING ERRCODE='PT404';END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public.share_factory_nine_snapshot(actor_id uuid, request_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE org uuid; project uuid; client uuid; req uuid; item jsonb; existing public.technology_next_shared_snapshots%rowtype; result uuid; role_name text;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'Server verified sharing required'; END IF;
 IF jsonb_typeof(request_payload) IS DISTINCT FROM 'object' OR octet_length(request_payload::text)>65536
 OR (SELECT count(*) FROM jsonb_object_keys(request_payload))<>6
 OR NOT request_payload ?& ARRAY['organizationId','projectId','clientWorkspaceId','requestId','title','snapshot'] THEN RAISE EXCEPTION 'Invalid sharing request'; END IF;
 IF jsonb_typeof(request_payload->'title') IS DISTINCT FROM 'string'
 OR jsonb_typeof(request_payload->'clientWorkspaceId') NOT IN('string','null') THEN RAISE EXCEPTION 'Invalid sharing request'; END IF;
 org:=(request_payload->>'organizationId')::uuid;project:=(request_payload->>'projectId')::uuid;
 client:=(request_payload->>'clientWorkspaceId')::uuid;req:=(request_payload->>'requestId')::uuid;item:=request_payload->'snapshot';
 IF actor_id IS NULL OR org IS NULL OR project IS NULL OR req IS NULL THEN RAISE EXCEPTION 'Sharing identity required'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Organization unavailable'; END IF;
 SELECT m.role INTO role_name FROM public.organization_members m WHERE m.organization_id=org AND m.user_id=actor_id FOR SHARE;
 IF role_name IS NULL OR role_name NOT IN('owner','admin','manager','member') THEN RAISE EXCEPTION 'Sharing role required'; END IF;
 PERFORM 1 FROM public.profiles p WHERE p.id=actor_id AND p.plan='business' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Business plan required'; END IF;
 PERFORM 1 FROM public.profiles p JOIN public.organizations o ON o.owner_user_id=p.id WHERE o.id=org AND p.plan='business' FOR SHARE OF p;
 IF NOT FOUND THEN RAISE EXCEPTION 'Business organization required'; END IF;
 PERFORM 1 FROM public.business_projects WHERE id=project AND organization_id=org AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Project unavailable'; END IF;
 IF client IS NOT NULL THEN
  PERFORM 1 FROM public.client_workspaces WHERE id=client AND organization_id=org AND (project_id IS NULL OR project_id=project) FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Client workspace unavailable'; END IF;
 END IF;
 IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>4
 OR NOT item ?& ARRAY['calculatorSlug','calculatorVersion','input','output'] OR jsonb_typeof(item->'calculatorVersion') IS DISTINCT FROM 'number'
 OR item->'calculatorVersion' IS DISTINCT FROM '1'::jsonb
 OR jsonb_typeof(item->'calculatorSlug') IS DISTINCT FROM 'string'
 OR item->>'calculatorSlug' NOT IN('square-calculator','cube-calculator','square-root-calculator','length-converter','energy-converter','power-converter','time-converter','force-converter','frequency-converter','percentage-change-calculator','percentage-increase-calculator','percentage-decrease-calculator','ratio-calculator','proportion-calculator','fraction-to-decimal-calculator','average-two-numbers-calculator','area-converter','volume-converter','temperature-converter','speed-converter','angle-converter','data-storage-converter','capacitance-calculator','free-fall-calculator','angular-velocity-calculator')
 OR jsonb_typeof(item->'input') IS DISTINCT FROM 'object' OR jsonb_typeof(item->'output') IS DISTINCT FROM 'object'
 OR NOT (CASE WHEN item->>'calculatorSlug' IN('capacitance-calculator','free-fall-calculator','angular-velocity-calculator') THEN (SELECT count(*) FROM jsonb_object_keys(item->'output'))=2 AND item->'output' ?& ARRAY['value','steps'] AND jsonb_typeof(item->'output'->'value')='number' AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string') ELSE (SELECT count(*) FROM jsonb_object_keys(item->'output'))=1 AND jsonb_typeof(item->'output'->'result')='number' END)
 OR char_length(request_payload->>'title') NOT BETWEEN 1 AND 240 THEN RAISE EXCEPTION 'Unsupported shared snapshot'; END IF;
 SELECT * INTO existing FROM public.technology_next_shared_snapshots s
 WHERE s.organization_id=org AND s.created_by=actor_id AND s.request_id=req;
 IF FOUND THEN
  IF existing.request_payload IS DISTINCT FROM request_payload THEN RAISE EXCEPTION 'Sharing request conflicts with original snapshot'; END IF;
  RETURN existing.id;
 END IF;
 INSERT INTO public.technology_next_shared_snapshots(organization_id,project_id,client_workspace_id,created_by,request_id,title,calculator_slug,calculator_version,input_data,output_data,request_payload)
 VALUES(org,project,client,actor_id,req,request_payload->>'title',item->>'calculatorSlug',(item->>'calculatorVersion')::integer,item->'input',item->'output',request_payload) RETURNING id INTO result;
 INSERT INTO public.organization_audit_log(organization_id,actor_user_id,action,entity_type,entity_id,metadata)
 VALUES(org,actor_id,'factory-nine.snapshot.shared','factory-nine-shared-snapshot',result::text,jsonb_build_object('calculatorSlug',item->>'calculatorSlug','calculatorVersion',(item->>'calculatorVersion')::integer,'projectId',project,'clientWorkspaceId',client));
 RETURN result;
END $function$
;
CREATE OR REPLACE FUNCTION public.submit_technology_five_job_v1(p_api_key_id uuid, p_key_hash text, p_organization_id uuid, p_request_id uuid, p_catalog_id integer, p_version integer, p_input_rows jsonb, p_output_rows jsonb, p_endpoint_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE issuer uuid;prior public.technology_five_jobs%ROWTYPE;j public.technology_five_jobs%ROWTYPE;payload jsonb;engine text;endpoint public.business_webhook_endpoints%ROWTYPE;event jsonb;duplicate boolean:=false;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Trusted service caller required' USING ERRCODE='PT403';END IF;
 IF current_setting('transaction_isolation')<>'read committed' OR p_request_id IS NULL OR jsonb_typeof(p_input_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_input_rows) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT FROM jsonb_array_elements(p_input_rows)r WHERE jsonb_typeof(r)<>'object') THEN RAISE EXCEPTION 'Invalid bounded batch';END IF;
 issuer:=public.technology_five_key_authority_v1(p_api_key_id,p_key_hash,p_organization_id);PERFORM public.technology_five_require_publication_v1(p_catalog_id,p_version);
 payload:=jsonb_build_object('catalogId',p_catalog_id,'version',p_version,'rows',p_input_rows,'webhookEndpointId',p_endpoint_id);
 SELECT * INTO prior FROM public.technology_five_jobs WHERE api_key_id=p_api_key_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.payload IS DISTINCT FROM payload OR prior.organization_id IS DISTINCT FROM p_organization_id OR prior.job_snapshot IS DISTINCT FROM public.technology_five_job_snapshot_v1(prior) THEN RAISE EXCEPTION 'Request identity conflicts with immutable batch' USING ERRCODE='PT409';END IF;j:=prior;duplicate:=true;
 ELSE
  IF p_output_rows IS NULL THEN RETURN jsonb_build_object('status','missing');END IF;
  IF jsonb_typeof(p_output_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_output_rows)<>jsonb_array_length(p_input_rows) OR EXISTS(SELECT FROM jsonb_array_elements(p_output_rows) WITH ORDINALITY r(row,n) WHERE jsonb_typeof(row)<>'object' OR row->'index' IS DISTINCT FROM to_jsonb(n-1) OR jsonb_typeof(row->'ok') IS DISTINCT FROM 'boolean' OR (row->'ok'='true'::jsonb AND (jsonb_typeof(row->'result') IS DISTINCT FROM 'object' OR row->'result'->'catalogId' IS DISTINCT FROM to_jsonb(p_catalog_id) OR row->'result'->'version' IS DISTINCT FROM to_jsonb(p_version))) OR (row->'ok'='false'::jsonb AND jsonb_typeof(row->'error') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'Invalid deterministic result rows';END IF;
  SELECT t.engine INTO engine FROM(VALUES(370,'technology.bandwidth'),(371,'technology.download-time'),(372,'technology.upload-time'),(373,'technology.data-transfer'),(386,'technology.base64-size'),(374,'technology.storage-conversion'),(377,'technology.aspect-ratio'),(378,'technology.resolution'),(379,'technology.dpi'),(382,'technology.power-supply'),(383,'technology.website-bandwidth'),(384,'technology.cloud-storage-cost'),(385,'technology.cloud-data-transfer-cost'),(369,'technology.cidr'),(375,'technology.raid-capacity'),(380,'technology.battery-runtime'),(381,'technology.ups-runtime'),(387,'technology.password-entropy'),(368,'technology.ip-subnet'),(376,'technology.screen-ppi'),(218,'launch-square-calculator'),(219,'launch-cube-calculator'),(220,'launch-square-root-calculator'),(423,'conversion.length'),(430,'conversion.energy'),(431,'conversion.power'),(432,'conversion.time'),(438,'conversion.force'),(440,'conversion.frequency'),(208,'launch-percentage-change-calculator'),(209,'launch-percentage-increase-calculator'),(210,'launch-percentage-decrease-calculator'),(211,'launch-ratio-calculator'),(212,'launch-proportion-calculator'),(215,'launch-fraction-to-decimal-calculator'),(216,'launch-average-two-numbers-calculator'),(424,'conversion.area'),(425,'conversion.volume'),(427,'conversion.temperature'),(428,'conversion.speed'),(433,'conversion.angle'),(434,'conversion.data-storage'),(322,'physics.capacitance'),(325,'physics.free-fall'),(327,'physics.angular-velocity'))t(id,engine) WHERE t.id=p_catalog_id;
  IF EXISTS(SELECT FROM jsonb_array_elements(p_output_rows)r WHERE r->'ok'='true'::jsonb AND r->'result'->>'engineId' IS DISTINCT FROM engine) THEN RAISE EXCEPTION 'Exact engine differs';END IF;
  IF p_endpoint_id IS NOT NULL THEN SELECT * INTO endpoint FROM public.business_webhook_endpoints WHERE id=p_endpoint_id AND organization_id=p_organization_id AND status='active' AND jsonb_typeof(event_types)='array' AND event_types ? 'calculation.completed' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Webhook endpoint unavailable' USING ERRCODE='PT403';END IF;END IF;
 END IF;
 -- Existing custom batch policy: one request unit per accepted POST, including
 -- duplicate POST; missing probe and GET recovery have no debit.
 IF NOT public.consume_native_business_api_quota_v1(p_api_key_id) THEN RAISE EXCEPTION 'API quota exceeded' USING ERRCODE='PT429';END IF;
 IF NOT duplicate THEN
  j.id:=gen_random_uuid();j.api_key_id:=p_api_key_id;j.organization_id:=p_organization_id;j.issuer_id:=issuer;j.request_id:=p_request_id;j.catalog_id:=p_catalog_id;j.engine_id:=engine;j.technical_version:=p_version;j.payload:=payload;j.input_rows:=p_input_rows;j.output_rows:=p_output_rows;j.created_at:=now();j.job_snapshot:=public.technology_five_job_snapshot_v1(j);
  INSERT INTO public.technology_five_jobs SELECT j.*;
  IF p_endpoint_id IS NOT NULL THEN
   event:=jsonb_build_object('id',j.id,'type','calculation.completed','created_at',to_char(j.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'data',j.job_snapshot);
   INSERT INTO public.technology_five_webhook_outbox(event_id,organization_id,api_key_id,issuer_id,endpoint_id,endpoint_snapshot,payload,payload_text) VALUES(j.id,p_organization_id,p_api_key_id,issuer,p_endpoint_id,jsonb_build_object('url',endpoint.endpoint_url,'secret_ciphertext',endpoint.secret_ciphertext,'created_by',endpoint.created_by),event,event::text);
  END IF;
 END IF;
 RETURN jsonb_build_object('status','completed','request_id',p_request_id,'duplicate',duplicate,'job',j.job_snapshot);
END $function$
;
CREATE OR REPLACE FUNCTION public.technology_five_require_publication_v1(p_catalog integer, p_version integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE engine text;slug text;
BEGIN
 SELECT t.engine,t.slug INTO engine,slug FROM (VALUES(370,'technology.bandwidth','bandwidth-calculator',1),(371,'technology.download-time','download-time-calculator',1),(372,'technology.upload-time','upload-time-calculator',1),(373,'technology.data-transfer','data-transfer-calculator',1),(386,'technology.base64-size','base64-size-calculator',1),(374,'technology.storage-conversion','storage-conversion-calculator',1),(377,'technology.aspect-ratio','aspect-ratio-calculator',1),(378,'technology.resolution','resolution-calculator',1),(379,'technology.dpi','dpi-calculator',1),(382,'technology.power-supply','power-supply-calculator',1),(383,'technology.website-bandwidth','website-bandwidth-calculator',2),(384,'technology.cloud-storage-cost','cloud-storage-cost-calculator',1),(385,'technology.cloud-data-transfer-cost','cloud-data-transfer-cost-calculator',1),(369,'technology.cidr','cidr-calculator',1),(375,'technology.raid-capacity','raid-capacity-calculator',1),(380,'technology.battery-runtime','battery-runtime-calculator',1),(381,'technology.ups-runtime','ups-runtime-calculator',1),(387,'technology.password-entropy','password-entropy-calculator',1),(368,'technology.ip-subnet','ip-subnet-calculator',1),(376,'technology.screen-ppi','screen-ppi-calculator',1),(218,'launch-square-calculator','square-calculator',1),(219,'launch-cube-calculator','cube-calculator',1),(220,'launch-square-root-calculator','square-root-calculator',1),(423,'conversion.length','length-converter',1),(430,'conversion.energy','energy-converter',1),(431,'conversion.power','power-converter',1),(432,'conversion.time','time-converter',1),(438,'conversion.force','force-converter',1),(440,'conversion.frequency','frequency-converter',1),(208,'launch-percentage-change-calculator','percentage-change-calculator',1),(209,'launch-percentage-increase-calculator','percentage-increase-calculator',1),(210,'launch-percentage-decrease-calculator','percentage-decrease-calculator',1),(211,'launch-ratio-calculator','ratio-calculator',1),(212,'launch-proportion-calculator','proportion-calculator',1),(215,'launch-fraction-to-decimal-calculator','fraction-to-decimal-calculator',1),(216,'launch-average-two-numbers-calculator','average-two-numbers-calculator',1),(424,'conversion.area','area-converter',1),(425,'conversion.volume','volume-converter',1),(427,'conversion.temperature','temperature-converter',1),(428,'conversion.speed','speed-converter',1),(433,'conversion.angle','angle-converter',1),(434,'conversion.data-storage','data-storage-converter',1),(322,'physics.capacitance','capacitance-calculator',1),(325,'physics.free-fall','free-fall-calculator',1),(327,'physics.angular-velocity','angular-velocity-calculator',1))t(catalog,engine,slug,version) WHERE t.catalog=p_catalog AND t.version=p_version;
 IF NOT FOUND OR NOT public.technology_five_publication_snapshot_v1(engine,slug,p_version) THEN RAISE EXCEPTION 'Exact publication unavailable' USING ERRCODE='PT404';END IF;
END $function$
;
COMMIT;
